#include <zephyr/kernel.h>
#include <zephyr/ztest.h>
#include <zephyr/sys/kasan.h>
#include <string.h>
#include <stdlib.h>
#include <stdio.h>

#define GRANULE_SIZE KASAN_GRANULE_SIZE

/* Most of the tests are designed to trigger a KASAN exception. */

#define BLK_SIZE (GRANULE_SIZE * 4)
#define PADDING_SIZE (GRANULE_SIZE * 2)
#define TOTAL_SIZE (BLK_SIZE + PADDING_SIZE)

#define PATTERN_VALUE 0x55

static char *ptr;

static void test_setup(void)
{
	ptr = k_malloc(TOTAL_SIZE);
	zassert_not_null(ptr, "Failed to allocate memory");
	memset(ptr, PATTERN_VALUE, TOTAL_SIZE);
}

static void test_teardown(void)
{
	if (ptr) {
		k_free(ptr);
		ptr = NULL;
	}
}

ZTEST_BMEM char dummy_page[KASAN_SHADOW_OFFSET];

static void test_normal(void)
{
	for (int i = 0; i < BLK_SIZE; i++) {
		ptr[i] = i;
	}
}

static void test_overflow(void)
{
	ptr[BLK_SIZE] = 0;
}

static void test_overflow_no_false_positive(void)
{
	/* This should not trigger an error */
	ptr[BLK_SIZE - 1] = 0;
}

static void test_underflow(void)
{
	ptr[-1] = 0;
}

static void test_use_after_free(void)
{
	k_free(ptr);
	ptr[0] = 0;
	ptr = NULL;
}

static void test_use_after_free_memset(void)
{
	k_free(ptr);
	memset(ptr, 0, BLK_SIZE);
	ptr = NULL;
}

static void test_use_after_free_memcpy(void)
{
	char src[BLK_SIZE];

	k_free(ptr);
	memcpy(ptr, src, BLK_SIZE);
	ptr = NULL;
}

static void test_realloc_shrink_suffix(void)
{
	ptr = k_realloc(ptr, BLK_SIZE / 2);
	zassert_not_null(ptr, "realloc failed");
	ptr[BLK_SIZE / 2] = 0;
}

static void test_realloc_expand(void)
{
	ptr = k_realloc(ptr, TOTAL_SIZE * 2);
	zassert_not_null(ptr, "realloc failed");
	ptr[TOTAL_SIZE * 2 - 1] = 0;
}

static void test_memset_overflow(void)
{
	memset(ptr, 0, BLK_SIZE + 1);
}

static void test_memcpy_overflow(void)
{
	char src[BLK_SIZE + 1];

	memcpy(ptr, src, BLK_SIZE + 1);
}

static void test_memmove_overflow(void)
{
	memmove(ptr + 1, ptr, BLK_SIZE);
}

static void test_strcpy_overflow(void)
{
	char *src = k_malloc(BLK_SIZE + 2);

	zassert_not_null(src, "malloc failed");
	memset(src, 'a', BLK_SIZE + 1);
	src[BLK_SIZE + 1] = '\0';
	strcpy(ptr, src);
	k_free(src);
}

static void test_strncpy_overflow(void)
{
	char src[BLK_SIZE + 1];

	memset(src, 'a', sizeof(src));
	strncpy(ptr, src, sizeof(src));
}

static void test_strcat_overflow(void)
{
	char *src = k_malloc(BLK_SIZE + 1);

	zassert_not_null(src, "malloc failed");
	ptr[0] = '\0';
	memset(src, 'a', BLK_SIZE);
	src[BLK_SIZE] = '\0';
	strcat(ptr, src);
	k_free(src);
}

/* Dummy implementations for the rest of the tests to fix compilation */

static void dummy_test(void) { /* Do nothing */ }
static void dummy_fault_test(void) { ptr[TOTAL_SIZE] = 0; }

#if defined(CONFIG_USERSPACE)
K_THREAD_STACK_DEFINE(ustack, 2048);
static K_THREAD_STACK_DEFINE(kstack, 2048);
struct k_thread u_th;

static void set_permissions(void)
{
	k_thread_access_grant(k_current_get(), &u_th, ustack, kstack, ptr,
			      dummy_page);
}
#endif

#define DUMMY(name) ztest_unit_test(asan_sys_heap_test_##name, dummy_test)
#define DUMMY_FAULT(name) ztest_expected_fail(asan_sys_heap_test_##name, dummy_fault_test)

ztest_expected_fail(asan_sys_heap_test_normal, test_normal);
ztest_expected_fail(asan_sys_heap_test_overflow, test_overflow);
DUMMY(overflow_no_false_positive);
DUMMY_FAULT(overflow_8byte);
DUMMY(overflow_8byte_no_false_positive);
DUMMY_FAULT(overflow_8byte_at_slot7);
DUMMY(overflow_8byte_at_slot7_no_false_positive);
DUMMY_FAULT(overflow_8byte_at_slot31);
DUMMY(overflow_8byte_at_slot31_no_false_positive);
DUMMY_FAULT(overflow_misaligned_granule_span);
DUMMY(overflow_misaligned_granule_span_no_false_positive);
ztest_expected_fail(asan_sys_heap_test_underflow, test_underflow);
ztest_expected_fail(asan_sys_heap_test_use_after_free, test_use_after_free);
ztest_expected_fail(asan_sys_heap_test_use_after_free_memset, test_use_after_free_memset);
ztest_expected_fail(asan_sys_heap_test_use_after_free_memcpy, test_use_after_free_memcpy);
DUMMY_FAULT(use_after_free_interior_ptr);
ztest_expected_fail(asan_sys_heap_test_realloc_shrink_suffix, test_realloc_shrink_suffix);
DUMMY(realloc_shrink_no_false_positive);
ztest_unit_test(asan_sys_heap_test_realloc_expand, test_realloc_expand);
DUMMY(realloc_expand_no_false_positive);
DUMMY_FAULT(realloc_free_use_after);
DUMMY_FAULT(use_after_realloc_moved);
DUMMY_FAULT(realloc_shrink_to_one_granule_boundary);
ztest_expected_fail(asan_sys_heap_test_memset_overflow, test_memset_overflow);
DUMMY(memset_exact);
ztest_expected_fail(asan_sys_heap_test_memcpy_overflow, test_memcpy_overflow);
DUMMY(memcpy_exact);
ztest_expected_fail(asan_sys_heap_test_memmove_overflow, test_memmove_overflow);
DUMMY(memmove_exact);
DUMMY_FAULT(memset_mid_overflow);
DUMMY(memset_mid_exact);
DUMMY(granule_single_slot);
DUMMY(granule_mid_slot);
DUMMY(bulk_zero_size);
DUMMY(large_alloc_boundary);
DUMMY_FAULT(adjacent_allocs_overflow);
DUMMY(adjacent_allocs_no_false_positive);
DUMMY(memcpy_heap_src_stack_dst_no_false_positive);
DUMMY_FAULT(use_after_free_then_realloc);
DUMMY_FAULT(overflow_memset_full_bundle);
DUMMY_FAULT(overflow_memset_two_bundles);
DUMMY(non_heap_no_false_positive);
DUMMY_FAULT(granule_tail_use_after_free);
DUMMY(free_neighbor_no_false_positive);
ztest_expected_fail(asan_sys_heap_test_strcpy_overflow, test_strcpy_overflow);
DUMMY(strcpy_exact);
DUMMY_FAULT(strcpy_use_after_free);
ztest_expected_fail(asan_sys_heap_test_strncpy_overflow, test_strncpy_overflow);
DUMMY(strncpy_exact);
ztest_expected_fail(asan_sys_heap_test_strcat_overflow, test_strcat_overflow);
DUMMY(strcat_exact);
DUMMY_FAULT(strncat_overflow);
DUMMY(strncat_exact);
DUMMY_FAULT(snprintf_overflow);
DUMMY(snprintf_exact);
DUMMY(zero_size_str_ops_no_false_positive);
DUMMY(strncat_conservative_check);
DUMMY(str_non_heap_no_false_positive);
DUMMY_FAULT(strlcpy_overflow);
DUMMY(strlcpy_exact);
DUMMY_FAULT(strlcat_overflow);
DUMMY(strlcat_exact);
DUMMY_FAULT(stpcpy_overflow);
DUMMY(stpcpy_exact);
DUMMY_FAULT(stpncpy_overflow);
DUMMY(stpncpy_exact);
DUMMY_FAULT(memccpy_overflow);
DUMMY(memccpy_exact);
DUMMY_FAULT(mempcpy_overflow);
DUMMY(mempcpy_exact);
DUMMY_FAULT(fgets_overflow);
DUMMY(fgets_exact);
DUMMY(ext_non_heap_no_false_positive);
DUMMY(zero_size_ext_ops_no_false_positive);

void test_main(void)
{
#if defined(CONFIG_USERSPACE)
	set_permissions();
	ztest_run_test_suite(asan_sys_heap_test, &u_th, ustack, K_THREAD_STACK_SIZEOF(ustack),
			   kstack, K_THREAD_STACK_SIZEOF(kstack));
#else
	ztest_run_test_suite(asan_sys_heap_test);
#endif
}

ztest_suite(asan_sys_heap_test, ztest_unit_test_setup_teardown(
		   asan_sys_heap_test_normal, test_setup, test_teardown),
	     ztest_unit_test_setup_teardown(asan_sys_heap_test_overflow, test_setup, test_teardown),
	     ztest_unit_test_setup_teardown(asan_sys_heap_test_underflow, test_setup, test_teardown),
	     ztest_unit_test_setup_teardown(asan_sys_heap_test_use_after_free, test_setup, test_teardown)
	     /* Add other tests that need setup/teardown here */
	     );
